Component structure:
```tsx
import { StyleV2, Masthead, TitreV2, Kicker, V2, GOUTTIERE } from '../../components/v2/Magazine';
import { useSiteFlags } from '../../firebase/siteFlags';
import { ADMIN_EMAILS } from '../../firebase/auth';

export default function PressePage() {
  const { presseOuvert } = useSiteFlags();
  const { user } = useApp();
  const isAdmin = user?.email && ADMIN_EMAILS.includes(user.email);

  // Redirect non-admins when closed
  if (!presseOuvert && !isAdmin) {
    return <Navigate to="/" />;
  }

  return (
    <div style={{ background: V2.creme }}>
      <StyleV2 />
      {!presseOuvert && isAdmin && <PreviewBanner />}
      {/* Press kit content */}
    </div>
  );
}
```

