import { Card, GhostButton } from '../primitives';

interface Post {
  id: string;
  caption: string;
  image: string;
  headline: string;
  body: string;
  cta: string;
  scheduled: string;
  status: 'ready' | 'generated' | 'published' | 'error';
}

const PostsSection: React.FC = () => {
  const [posts, setPosts] = useState<Post[]>([]);

  useEffect(() => {
    // Fetch scripts/posts/file.json
    fetch('/pubs/posts/file.json')
      .then(r => r.json())
      .then(setPosts);
  }, []);

  return (
    <div className="p-8">
      <h2>Posts préfaits</h2>
      <div className="grid grid-cols-3 gap-4">
        {posts.map(post => (
          <PostCard key={post.id} post={post} />
        ))}
      </div>
    </div>
  );
};
```
